"use client";
/* Gem, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Gem(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("gem"); }, []);
  return React.createElement("piix-pal", { "pal": "gem", ...piixAttrs(props) });
}

export default Gem;
